package main

const reviewHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>收藏方案审核</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101923;color:#e8eef2;font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{padding:24px;max-width:1500px;margin:auto}h1{font-size:24px;margin:0 0 8px}p,small{color:#9eb0bb;line-height:1.6}.layout{display:grid;grid-template-columns:260px 1fr;gap:16px}.panel{background:#1b2a38;border:1px solid #344b5c;border-radius:9px;padding:16px;margin:14px 0}.tree{max-height:68vh;overflow:auto}.tree button{display:block;width:100%;text-align:left;margin:0;border-radius:0;background:transparent;border:0;border-bottom:1px solid #2c4050}.tree button.active{background:#245877}.tree .count{float:right;color:#9eb0bb}button{padding:9px 12px;margin:4px 4px 4px 0;border:1px solid #42647a;border-radius:5px;background:#1d6fa3;color:white;cursor:pointer}button.secondary{background:#293d4c}button:disabled{opacity:.4;cursor:default}input,select{padding:9px;border-radius:5px;border:1px solid #416076;background:#101923;color:#e8eef2;font:inherit;max-width:100%}input[type=checkbox]{width:17px;height:17px}#search{width:100%;margin:10px 0}.table{max-height:57vh;overflow:auto}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:10px;border-bottom:1px solid #344b5c}th{position:sticky;top:0;background:#253b4b}td small{display:block}.toolbar{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.banner{background:#203c4c;border-left:3px solid #6bc4ef;padding:12px;line-height:1.6}#status{color:#f2c46d}.changed{color:#8dd8b0}h2{font-size:16px}.meta{display:flex;justify-content:space-between;gap:12px}@media(max-width:750px){.layout{display:block}.tree{max-height:220px}main{padding:12px}}
</style></head><body><main><div class="meta"><div><h1 id="title">收藏方案审核</h1><p id="meta">正在读取草稿…</p></div><button class="secondary" onclick="closePane()">关闭窗口</button></div><div class="banner">在此检查、搜索和调整草稿。接受后载入主界面的“待保存方案”，点击主界面“确认保存到 Steam”才会修改 Steam。动态收藏只展示现有成员，规则由你在 Steam 创建维护。</div><div class="layout"><aside class="panel"><h2>草稿收藏</h2><div id="tree" class="tree"></div></aside><section class="panel"><h2 id="heading">全部游戏</h2><div class="toolbar"><input id="bulk" list="targets" placeholder="输入或选择目标静态收藏"><datalist id="targets"></datalist><button onclick="bulkEdit()">调整选中游戏</button><button class="secondary" onclick="selectPage()">全选/取消本页</button></div><input id="search" placeholder="搜索名称、AppID、当前或草稿收藏" oninput="page=0;render()"><div class="table"><table><thead><tr><th></th><th>游戏</th><th>当前 Steam 收藏</th><th>草稿静态收藏</th><th>发行厂商</th><th>最后游玩 / 时长</th></tr></thead><tbody id="games"></tbody></table></div><div class="toolbar"><button class="secondary" onclick="page=Math.max(0,page-1);render()">上一页</button><span id="pageInfo"></span><button class="secondary" onclick="page++;render()">下一页</button></div></section></div><section class="panel"><div id="summary"></div><div class="toolbar"><button id="accept" disabled onclick="accept()">接受并载入主表</button><button class="secondary" onclick="reject()">放弃草稿</button><span id="status"></span></div></section></main><script>
let draft=null,payload=null,snapshot=null,selected='',page=0,pages=1,checked=new Set(),initial=null;
const $=s=>document.querySelector(s);const clone=x=>JSON.parse(JSON.stringify(x));const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,body){let r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});return r.json()}
const reviewHost=window.opener||(window.parent!==window?window.parent:null);
function notifyHost(type){if(!reviewHost)return;try{reviewHost.postMessage({type},location.origin)}catch(e){}}
function closePane(){notifyHost('review-close');try{window.close()}catch(e){}}
function msg(s){$('#status').textContent=s}
function dynamicCols(){let all=[...(snapshot?.collections||[]),...(draft?.collection_state?.collections||[])];return [...new Map(all.filter(c=>c.dynamic).map(c=>[c.id,c])).values()]}
function isDynamic(name){return dynamicCols().some(c=>c.name===name)}
function memberships(id,cols){return (cols||[]).filter(c=>!c.dynamic&&(!c.system||c.id==='favorite')&&(c.appids||[]).includes(id)).map(c=>c.name)}
let targetIndex=new Map(),targetCounts=new Map();
function indexTargets(){targetIndex=new Map();targetCounts=new Map();if(draft.collection_state){for(let c of draft.collection_state.collections||[])if(!c.dynamic&&(!c.system||c.id==='favorite'))for(let id of c.appids||[]){if(!targetIndex.has(id))targetIndex.set(id,[]);targetIndex.get(id).push(c.name);targetCounts.set(c.name,(targetCounts.get(c.name)||0)+1)}}else for(let g of draft.games){let ns=g.target&&g.target!=='未分类'?[g.target]:[];targetIndex.set(g.appid,ns);for(let n of ns)targetCounts.set(n,(targetCounts.get(n)||0)+1)}}
function targets(g){return targetIndex.get(g.appid)||[]}
function names(){return [...new Set([...(draft.collection_order||[]).filter(n=>targetCounts.has(n)),...targetCounts.keys()])].filter(Boolean)}
function renderTree(){let el=$('#tree');el.innerHTML='';function add(n,count,key){let b=document.createElement('button');b.className=selected===key?'active':'';b.innerHTML=esc(n)+'<span class="count">'+count+'</span>';b.onclick=()=>{selected=key;page=0;render()};el.appendChild(b)}add('全部游戏',draft.games.length,'');add('未分类',draft.games.filter(g=>!targets(g).length).length,'unclassified');for(let n of names())add(n,(targetCounts.get(n)||0),'static:'+n);if(dynamicCols().length){let p=document.createElement('p');p.textContent='动态收藏 · 只读';el.appendChild(p)}for(let c of dynamicCols())add(c.name,(c.appids||[]).length,'dynamic:'+c.id);$('#targets').innerHTML=names().filter(n=>!isDynamic(n)).concat('未分类').map(n=>'<option value="'+esc(n)+'">').join('')}
function render(){if(!draft)return;indexTargets();renderTree();let q=$('#search').value.toLowerCase(),gs=draft.games.filter(g=>{let match=!selected||selected==='unclassified'&&!targets(g).length||selected.startsWith('static:')&&targets(g).includes(selected.slice(7))||selected.startsWith('dynamic:')&&(dynamicCols().find(c=>c.id===selected.slice(8))?.appids||[]).includes(g.appid);return match&&(g.name+' '+g.appid+' '+targets(g).join(' ')+' '+memberships(g.appid,snapshot?.collections).join(' ')).toLowerCase().includes(q)});pages=Math.max(1,Math.ceil(gs.length/50));page=Math.max(0,Math.min(page,pages-1));$('#heading').textContent=(selected?selected.slice(selected.indexOf(':')+1):'全部游戏')+' · '+gs.length+' 款';$('#pageInfo').textContent=(page+1)+' / '+pages+' 页';let body=$('#games');body.innerHTML='';let currentIDs=new Set((snapshot?.apps||[]).map(a=>a.appid));for(let g of gs.slice(page*50,(page+1)*50)){let tr=document.createElement('tr'),current=memberships(g.appid,snapshot?.collections),a=(snapshot?.apps||draft.collection_state?.apps||[]).find(a=>a.appid===g.appid)||{},p=g.publishers||[];tr.innerHTML='<td></td><td><b>'+esc(g.name)+'</b><small>'+g.appid+(snapshot?.apps?.length&&!currentIDs.has(g.appid)?' · 当前库未找到':'')+'</small><small>'+esc(g.reason||'')+'</small></td><td>'+esc(snapshot?.apps?.length?(current.join('；')||'未分类'):'尚未读取')+'</td><td class="changed">'+esc(targets(g).join('；')||'未分类')+'</td><td>'+esc(p.join('；')||'待查询')+'</td><td>'+esc(a.last_played?new Date(a.last_played*1000).toLocaleString():'无记录')+'<small>'+esc(a.playtime_minutes===undefined?'时长未提供':(a.playtime_minutes/60).toFixed(1)+' 小时')+'</small></td>';let cb=document.createElement('input');cb.type='checkbox';cb.checked=checked.has(g.appid);cb.onchange=()=>{if(cb.checked)checked.add(g.appid);else checked.delete(g.appid)};cb.dataset.id=g.appid;tr.firstChild.appendChild(cb);body.appendChild(tr)}let changed=draft.games.filter(g=>targets(g).slice().sort().join('|')!==memberships(g.appid,snapshot?.collections).sort().join('|')).length;$('#summary').textContent=draft.games.length+' 款 · '+names().length+' 个静态目标 · '+(snapshot?.apps?.length?changed+' 款与当前静态收藏不同':'Steam 尚未读取，无法比较')+(draft.collection_state?' · 原始收藏快照模式，保留多个静态归属':' · 每款一个静态目标')}
function edit(ids,name){name=name.trim();if(!name)return msg('请输入目标收藏');if(isDynamic(name))return msg('动态收藏由你在 Steam 维护，请选择静态名称');if(draft.collection_state){for(let c of draft.collection_state.collections)if(!c.dynamic&&(!c.system||c.id==='favorite'))c.appids=(c.appids||[]).filter(id=>!ids.has(id));if(name!=='未分类'){let c=draft.collection_state.collections.find(c=>!c.dynamic&&(!c.system||c.id==='favorite')&&c.name===name);if(!c){c={id:'draft-'+Date.now(),name,dynamic:false,system:false,editable:true,deletable:true,appids:[]};draft.collection_state.collections.push(c)}c.appids=[...new Set([...c.appids,...ids])]}}for(let g of draft.games)if(ids.has(g.appid)){g.target=name;g.priority=6;g.dynamic_only_if_matched=false}if(name!=='未分类'&&!(draft.collection_order||[]).includes(name))(draft.collection_order??=[]).push(name);checked.clear();render();msg('草稿已调整，其他游戏和动态归属保持不变')}
function bulkEdit(){if(!checked.size)return msg('请先选择游戏');edit(checked,$('#bulk').value)}function selectPage(){let boxes=[...document.querySelectorAll('#games input')],all=boxes.every(b=>b.checked);for(let b of boxes){b.checked=!all;if(all)checked.delete(Number(b.dataset.id));else checked.add(Number(b.dataset.id))}}
async function load(p){payload=p;draft=clone(p.manifest);initial=clone(draft);let state=await api('/api/state');snapshot=state.snapshot;$('#title').textContent=p.kind||'收藏方案审核';$('#meta').textContent=p.source||'草稿';$('#accept').disabled=false;render()}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='steam-draft')load(e.data)});
async function accept(){if(!draft)return;$('#accept').disabled=true;try{let x=await api('/api/draft',{manifest:draft,kind:payload?.kind||'审核草稿',source:payload?.source||'审核窗口'});if(!x.ok)return msg(x.error);x=await api('/api/draft/accept',{});if(!x.ok)return msg(x.error);notifyHost('draft-accepted');msg('已载入主表，等待预览保存');closePane()}finally{$('#accept').disabled=false}}
function reject(){notifyHost('draft-rejected');closePane()}
notifyHost('review-ready');
if(!new URLSearchParams(location.search).has('wait'))api('/api/state').then(s=>{if(s.draft&&!draft)load({manifest:s.draft,kind:s.draft_kind,source:s.draft_source})});
</script></body></html>`
